               JOIN net._http_response x ON x.id::text = e.detalhes->>'request_id'
              WHERE e.acao = c_acao AND e.detalhes->>'arquivo' = c_arquivo) THEN
    RAISE EXCEPTION 'RESOLVE: a resposta do 057 ainda esta em net._http_response — use a colheita normal';
  END IF;
  IF c_resposta->>'versao' IS DISTINCT FROM 'v1.3-sensor-do-valor-plano-por-id-escrita-na-janela'
     OR (c_resposta->>'dry_run')::boolean IS NOT TRUE
     OR (c_resposta->>'completo')::boolean IS NOT TRUE
     OR (c_resposta->>'paginas_lidas')::int IS DISTINCT FROM 1 THEN
    RAISE EXCEPTION 'RESOLVE: a copia local nao confere com o disparo 057';
  END IF;

  UPDATE public.acoes_execucoes
     SET status = 'sucesso',
         finalizado_em = timestamptz '2026-09-11 01:47:30+00',
         detalhes = detalhes || jsonb_build_object('colheita', jsonb_build_object(
           'status_code', 200,
           'timed_out', false,
           'error_msg', null,
           'resposta', c_resposta,
           'origem_da_copia', 'leitura psql-ro de 2026-09-11 01:47:30Z (ler-disparo.sh); net._http_response purgado antes da colheita',
           'sha256_copia_local', c_sha,
           'colhido_em', clock_timestamp()))
   WHERE acao = c_acao
     AND detalhes->>'arquivo' = c_arquivo
     AND detalhes->>'request_id' = '75873'
     AND status = 'executando';
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n = 0 AND EXISTS (SELECT 1 FROM public.acoes_execucoes
                          WHERE acao = c_acao AND detalhes->>'arquivo' = c_arquivo
                            AND detalhes->'colheita'->>'sha256_copia_local' = c_sha) THEN
    RAISE NOTICE 'RESOLVE_OK 057 ja estava fechado com esta mesma copia';
  ELSIF v_n <> 1 THEN
    RAISE EXCEPTION 'RESOLVE: esperava fechar exatamente 1 linha executando do 057, fechou %', v_n;
  END IF;

  -- POSTCONDIÇÃO: nenhuma invocação desta ação segue 'executando' (a trava fica livre).
  IF EXISTS (SELECT 1 FROM public.acoes_execucoes WHERE acao = c_acao AND status = 'executando') THEN
    RAISE EXCEPTION 'RESOLVE: ainda ha linha executando — postcondicao falhou';
  END IF;
  RAISE NOTICE 'RESOLVE_OK 057 fechado com a copia local sha256=%', left(c_sha, 16);
END
$resolve$;
